"""One-off helper — writes drafts already generated by `draft` (see
`draft --include-synced`) onto Notion pages that exist already, because `sync`
only writes fields when it CREATES a page.

Per lead with a draft: finds its page through the seen_domains.json cache, and
writes Suggested Channel + Draft Message ONLY if the page's Draft Message is
empty (never overwrites), and Status -> Queued ONLY if it is "Not started".
Nothing else on the page is touched. Defaults to a dry run; pass --yes to write.

Usage:
    .venv/bin/python scripts/backfill_drafts.py --run RUN [--run RUN2]          # dry run
    .venv/bin/python scripts/backfill_drafts.py --run RUN [--run RUN2] --yes    # write
"""

from __future__ import annotations

import argparse
import sys
import time
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

import requests

from pipeline.config import ConfigError, load_config, load_env
from pipeline.schema import Lead, read_jsonl
from pipeline.sinks.notion_sink import _text, cache_key, load_seen

API_BASE = "https://api.notion.com/v1"


def plan_update(lead: Lead, page: dict) -> dict | None:
    """Properties to write for one page, or None when it must be left alone."""
    props = page["properties"]
    if "".join(t.get("plain_text", "") for t in props["Draft Message"]["rich_text"]):
        return None  # already has a draft — never overwrite
    update = {
        "Suggested Channel": {"select": {"name": lead.suggested_channel}},
        "Draft Message": _text(lead.draft_message[:2000]),
    }
    status = (props["Status"]["select"] or {}).get("name")
    if status == "Not started" and lead.qualified:
        update["Status"] = {"select": {"name": "Queued"}}
    return update


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", default="config.yaml")
    parser.add_argument("--run", action="append", required=True, help="run id (repeatable)")
    parser.add_argument("--yes", action="store_true", help="write changes (default: dry run)")
    args = parser.parse_args(argv)

    try:
        config = load_config(args.config)
    except ConfigError as e:
        print(f"error: {e}", file=sys.stderr)
        return 1
    notion, env = config["notion"], load_env()
    token = env.get("NOTION_TOKEN", "")
    if not token:
        print("error: NOTION_TOKEN not set (see README Notion setup)", file=sys.stderr)
        return 1
    headers = {
        "Authorization": f"Bearer {token}",
        "Notion-Version": notion["api_version"],
        "Content-Type": "application/json",
    }
    seen = load_seen(notion["cache_path"])
    session = requests.Session()

    leads: dict[str, Lead] = {}
    for run in args.run:
        for lead in read_jsonl(Path("data/runs") / run / "scored.jsonl"):
            if lead.draft_message:
                leads.setdefault(cache_key(lead), lead)  # first draft wins across runs

    written = skipped = missing = 0
    for key, lead in leads.items():
        entry = seen.get(key)
        if not entry:
            missing += 1
            print(f"  no page in cache: {lead.company}")
            continue
        r = session.get(f"{API_BASE}/pages/{entry['page_id']}", headers=headers, timeout=notion["timeout_s"])
        r.raise_for_status()
        update = plan_update(lead, r.json())
        if update is None:
            skipped += 1
            continue
        print(f"  {'write' if args.yes else 'would write'}: {lead.company} -> {lead.suggested_channel}, {len(lead.draft_message)} chars")
        if args.yes:
            r = session.patch(
                f"{API_BASE}/pages/{entry['page_id']}",
                headers=headers,
                json={"properties": update},
                timeout=notion["timeout_s"],
            )
            r.raise_for_status()
            time.sleep(notion["delay_s"])
        written += 1
    print(f"{written} {'written' if args.yes else 'would be written'}, {skipped} left alone (already have a draft), {missing} without a page")
    if written and not args.yes:
        print("dry run — pass --yes to write")
    return 0


if __name__ == "__main__":
    sys.exit(main())
